import { test } from "node:test";
import assert from "node:assert/strict";
import { cartTotal } from "../src/cart.js";

test("cartTotal of an empty items list is 0", () => {
  assert.equal(cartTotal({ items: [] }), 0);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { cartTotal } from "../src/cart.js";

test("cartTotal of a zero-quantity line is 0", () => {
  assert.equal(cartTotal({ items: [{ priceCents: 100, quantity: 0 }] }), 0);
});
